<div class="grid gap-5 md:grid-cols-2"><div class="md:col-span-2"><x-ui.select name="product_return_id" label="Retour textile" :value="$item->product_return_id" :options="$returns->mapWithKeys(fn($x)=>[$x->id=>$x->reference.' · '.$x->product->name])" required/></div><x-ui.input name="recycled_percent" label="Part recyclée (%)" type="number" :value="$item->recycled_percent ?: 0" min="0" max="100" step="0.01" required/><x-ui.input name="reused_percent" label="Part réemployée (%)" type="number" :value="$item->reused_percent ?: 0" min="0" max="100" step="0.01" required/><x-ui.input name="waste_percent" label="Part déchet (%)" type="number" :value="$item->waste_percent ?: 0" min="0" max="100" step="0.01" required/><x-ui.input name="processed_at" label="Date du traitement" type="datetime-local" :value="optional($item->processed_at)->format('Y-m-d\TH:i')"/><div class="md:col-span-2 rounded-xl bg-amber-50 p-4 text-sm font-semibold text-amber-800">La somme des trois pourcentages doit être égale à 100 %.</div><div class="md:col-span-2"><x-ui.textarea name="notes" label="Notes de traitement" :value="$item->notes"/></div></div>
